def bundle(value):return ', '.join(f'{RESOURCE_NAMES.get(k,k)} {v:g}' for k,v in value.items()) or '—'
def polish(text):
    text=re.sub(r'([А-Яа-яЁё])(?=\d)',r'\1 ',text)
    text=re.sub(r'(\d)(?=[А-Яа-яЁё])',r'\1 ',text)
    return text.replace('Python3.12','Python 3.12').replace('pygame2.6.1','pygame 2.6.1').replace('эпохаII','эпоха II').replace('эпохаI','эпоха I').replace('эпохиII','эпохи II').replace('эпохиI','эпохи I').replace('ЭПОХАII','ЭПОХА II')
def table(headers,rows):
    safe=lambda v:str(v).replace('|',' / ').replace('\n','<br>')
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join('---' for _ in headers)+' |']+['| '+' | '.join(map(safe,row))+' |' for row in rows])+'\n'

def generate():
    docs=ROOT/'docs';docs.mkdir(exist_ok=True)
    assert set(ACTION_HELP)==set(PRICES),set(PRICES)-set(ACTION_HELP)
    out=['# Все действия нейросети\n','Справочник сформирован из реального реестра движка. Всего '+str(len(PRICES))+' типов. Каждый приказ имеет `type` и `args`. До12 приказов в основном ответе; `count` не равен количеству слотов. `cell=[x,y]`, координаты целые и начинаются с0. Все проверки и стоимость применяет движок.\n']
    for name in PRICES:
        fields,required=CONTRACTS[name]
        out += ['## '+name+'\n',ACTION_HELP[name]+'\n',table(['Аргумент','Обязателен','Тип / ограничение'],[(k,'да' if k in required else 'нет',json.dumps(v,ensure_ascii=False,separators=(',',':'))) for k,v in fields.items()]) if fields else 'Аргументов нет.\n']
    out+=['## Обработка отказа\n','Отказ записывается в `previous_outcome.action_results` с `success=false` и причиной. Успех проверяется по состоянию и квитанциям, а не тексту `thinking`. Простые ошибочные приказы проверяются до списаний; группа найма проверяется целиком. В наборе разных приказов предыдущие успешные действия не откатываются из-за следующего отказа. Повторный день не должен повторно применять уже сохранённое общее исполнение.\n']
    (docs/'ACTIONS.md').write_text('\n'.join(out),encoding='utf-8')
    out=['# Каталоги ресурсов, технологий, зданий и армий\n','Числа берутся из каталогов той же версии кода. Это игровые величины. Дополнительные требования места/эпохи/снабжения проверяются движком; стоимость не означает доступность.\n','## Ресурсы\n',table(['ID','Название','Доступность'],[(k,v,'эпохаI иII' if k in BASE_RESOURCES else 'только личная эпохаII') for k,v in RESOURCE_NAMES.items()]),'## Технологии первой эпохи\n',table(['ID / название','Предпосылки','Цена','Эффект'],[(k+' / '+v['name'],', '.join(v['requires']) or '—',bundle({x:v[x] for x in ('money','science','matter') if v[x]}),v['effect']) for k,v in BASE_TECHS.items()]),'## Эпохальный переход и технологии второй эпохи\n',table(['ID / название','Предпосылки','Цена','Специальное место','Эффект'],[(k+' / '+v['name'],', '.join(v['requires']) or '—',bundle(v['cost']),v.get('site') or 'подходящее научное здание',v['effect']) for k,v in TECHNOLOGIES.items()]),'## Здания первой эпохи\n',table(['Тип','Выход / эффект'],[(k,v) for k,v in dict(lab='Наука10×уровень; только science',castle='Деньги10×уровень',mine='Металл10×уровень; mountain/resource',tavern='Деньги10×уровень',arsenal='Материя10×уровень',tower='После полного дня гарнизона +25% силы за уровень на3 дня',wall='20 прочности за уровень; осада боевыми частями').items()]),'Цена старого здания: 200 денег (160 с engineering) плюс20 сырья на уровень (15 с masonry). Уровни1–10. Для производящих зданий без жителя выход умножается на0.1; технологии могут давать дополнительные множители. Стена и башня не производят базовый ресурс.\n','## Промышленные и оборонительные здания\n']
    for key,v in BUILDINGS.items():
        extra={k:x for k,x in v.items() if k not in ('name','tech','workers','cost','inputs','outputs','capacity','max_level','priority')}
        out+=['### '+v['name']+' · '+key+'\n',table(['Свойство','Значение'],[('Технология',v['tech']),('Цена уровня',bundle(v['cost'])),('Рабочих на уровень',v['workers']),('Входы / день / уровень',bundle(v['inputs'])),('Выходы / день / уровень',bundle(v['outputs'])),('Вместимость клетки',v['capacity']),('Максимальный уровень',v['max_level']),('Базовый приоритет',v['priority'])]+[(k,json.dumps(x,ensure_ascii=False)) for k,x in extra.items()])]
    out+=['## Базовые юниты\n',table(['Тип','Базовая скорость','Сила','Среда'],[('scout',4,'1–10','суша'),('builder',3,'1–10','суша'),('army',2,'1–10','суша'),('ship',4,'1–10','вода')]),'Шаг2 денег, атака дополнительно20. Сила выше5 требует army для обычного сухопутного найма. Технологии меняют скорость/цену. Армии и стены участвуют в осаде; разведчик не является заменой боевой части.\n','## Современные армии\n']
    world=World(size=24,count=2)
    for key,v in UNITS.items():
        out+=['### '+v['name']+' · '+key+'\n',table(['Свойство','Значение'],[('Технология',v['tech']),('Сила',v['strength']),('Шагов в день',v['speed']),('Граждан на экипаж',v['crew']),('Полная цена найма',bundle(world.modern_recruitment_cost(key))),('Деньги / день',v['money']),('Еда / день',v['crew']*2),('Топливо / день',v['fuel']),('Оружие / день',f"{v['weapon']}: {max(1,v['weapons']*.025):g}"),('Дальность bombard',v.get('range','нет')),('Перехват / радиус',f"{v.get('intercept',0)} / {v.get('radius',0)}")])]
    out+=['Логистика уменьшает ежедневные топливо и оружие на25%; недоснабжение снижает эффективную силу и вызывает износ. Экипаж вычитается из гражданского населения, поэтому найм уменьшает рабочую силу.\n','## Ракеты\n',table(['Ресурс','Технология','Дальность','Урон','Пробитие','Радиус'],[(k,v['tech'],v['range'],v['damage'],v['penetration'],v['area']) for k,v in MISSILES.items()])]
    (docs/'CATALOGS.md').write_text('\n'.join(out),encoding='utf-8')
    types={k:type(v).__name__ for k,v in DEFAULTS.items()}
    (docs/'CONFIGURATION.md').write_text('# Все параметры конфигурации\n\nРабочий `config.json` создаётся на первом запуске и игнорируется Git. Значения ниже — чистые настройки7.5.4; они не взяты с компьютера автора.\n\n'+table(['Ключ','Тип','По умолчанию'],[(k,types[k],json.dumps(v,ensure_ascii=False)) for k,v in DEFAULTS.items()])+'\n## Связь лимитов\n\n`context_window` — общее запрошенное окно; `input_tokens` — желаемый бюджет фактов; `max_tokens` — верхний предел ответа. Вместе с системными инструкциями и техническим запасом они должны поместиться в подтверждённое окно модели. Игра может уменьшить резерв ответа или использовать больше целевого входа, чтобы сохранить текущие данные. Это не обещание выделить неподдерживаемую память.\n\n## Режимы\n\n`strict_state_isolation=true` требует нативного LM Studio API: выгрузка и загрузка чистого экземпляра между владельцами. `manage_model_context` управляет загрузкой вне строгого режима. Для стороннего OpenAI-совместимого сервера без этих методов оба параметра выключают; такой режим не обеспечивает серверную проверку выгрузки. `local_execution` и `local_chronicle` оставляют подготовку приказов и главы локальными. Отключение возвращает дополнительные запросы. `external_console` открывает отдельную консоль только в Windows. `response_max_bytes` ограничивает принимаемый ответ, а не контекст. Остальные архивные лимиты задают максимум истории, передаваемой в запрос, а не срок хранения сохранения.\n',encoding='utf-8')
    with (docs/'CONFIGURATION.md').open('a',encoding='utf-8') as extra:extra.write('\n[Подробно о лимитах и памяти](LIMITS.md).\n')
    for name in ('ACTIONS.md','CATALOGS.md','CONFIGURATION.md'):
        path=docs/name;path.write_text(polish(path.read_text(encoding='utf-8')),encoding='utf-8')
    return dict(actions=len(PRICES),resources=len(RESOURCE_NAMES),base_technologies=len(BASE_TECHS),modern_technologies=len(TECHNOLOGIES),modern_buildings=len(BUILDINGS),modern_units=len(UNITS))

if __name__=='__main__':print(json.dumps(generate()))
